#!/system/bin/sh
M=${1:-manual};A=/storage/emulated/0/Android/data/com.omarea.vtools;B=/data/media/0/Android/data/com.omarea.vtools;T=/data/local/tmp/scene-adb-stage;D=${0%/*};p(){ echo "[$(date)] $*"; };b(){ i=0;while [ $i -lt 90 ];do [ "$(getprop sys.boot_completed)" = 1 ]&&return 0;i=$((i+1));sleep 2;done;return 0; };f(){ [ -f "$A/up.sh" ]&&return 0;[ -f "$B/up.sh" ]&&A=$B&&return 0;return 1; };w(){ i=0;while [ $i -lt 300 ];do f&&return 0;i=$((i+1));sleep 2;done;return 1; };g(){ rm -rf "$T";mkdir -p "$T/toolkit";chmod 755 "$T" "$T/toolkit";cp -f "$A/daemon" "$T/daemon"||return 1;cp -f "$A/toolkit/busybox" "$T/toolkit/busybox"||return 1;[ -f "$A/binder.so" ]&&cp -f "$A/binder.so" "$T/binder.so";cp -f "$D/scene-up.sh" "$T/scene-up.sh"||return 1;chmod 755 "$T" "$T/toolkit" "$T/scene-up.sh" "$T/daemon" "$T/toolkit/busybox";[ -f "$T/binder.so" ]&&chmod 755 "$T/binder.so";return 0; };c(){ killall scene-daemon 2>/dev/null||true;rm -f /data/local/tmp/scene-daemon /data/local/tmp/binder.so;rm -rf /data/local/tmp/toolkit;mkdir -p /data/local/tmp/toolkit;chmod 777 /data/local/tmp/toolkit; };p "started mode=$M";S=0;[ "$M" = boot -o "$M" = manual-no-start ]&&S=1;if [ "$M" = boot ];then b;sleep 10;P=$(pidof scene-daemon 2>/dev/null);[ -n "$P" ]&&p "already running pid=$P"&&exit 0;w||{ p "missing files";exit 1; };else f||{ p "missing files";echo "Missing required files";exit 1; };fi;g||{ p "stage failed";exit 1; };c;p "launching";/system/bin/su 2000 -c "SCENE_SKIP_START=$S sh $T/scene-up.sh";s=$?;p "exit=$s pid=$(pidof scene-daemon 2>/dev/null)";exit "$s"
